// Accedemos al campo stdout del nodo anterior
let stdout = $input.first().json.stdout;

// Normalizamos los saltos de línea si n8n los está mostrando como caracteres literales '\n'
stdout = stdout.replace(/\\n/g, '\n');

// Expresión regular para capturar bloques que inician con [Exception]:
const exceptionRegex = /\[Exception\]:([\s\S]*?)(?=\n\[Exception\]:|$)/g;

// Usaremos un objeto como diccionario para agrupar las excepciones únicas
const uniqueExceptions = {};
let match;

// Iteramos sobre todas las excepciones encontradas en el log
while ((match = exceptionRegex.exec(stdout)) !== null) {
    let rawException = match[1].trim();
    let lines = rawException.split('\n');

    // Extraemos la firma (signature) y el stack trace
    let signature = lines[0].trim();
    let stackTrace = lines.slice(1).join('\n').trim();

    // Verificamos si esta firma ya existe en nuestro diccionario
    if (!uniqueExceptions[signature]) {
        // Si no existe, la registramos por primera vez
        uniqueExceptions[signature] = {
            type: "Exception",
            signature: signature,
            stackTrace: stackTrace,
            fullError: match[0].trim(),
            occurrences: 1 // Iniciamos el contador
        };
    } else {
        // Si ya existe, simplemente incrementamos el contador de incidencias
        uniqueExceptions[signature].occurrences++;
    }
}

// Convertimos el diccionario con los valores únicos de vuelta al formato de array que n8n espera
const exceptions = Object.values(uniqueExceptions).map(item => {
    return { json: item };
});

// Si no se encuentran excepciones, devolvemos un mensaje
if (exceptions.length === 0) {
    return [{ json: { status: "No exceptions found", originalLog: stdout } }];
}

// n8n procesará cada excepción única en el array
return exceptions;
